window.RECIPES = [{"title": "Serniczki kwargowe pieczone", "sub": "Mini serniki z kvargu — na słodko bez wyrzutów sumienia", "img": "img/r1.jpg", "time": "35 min", "macro": {"protein": 11, "kcal": 95}, "ingredients": ["500 g kvargu naturalnego (np. Lindahls/Kesam, ~10 g P/100 g)", "2 jajka", "30 g waniliowego proteinpulveru (lub 20 g mąki migdałowej + słodzik)", "1 łyżeczka ekstraktu waniliowego", "Słodzik do smaku (np. sukraloza/stevia)", "Garść borówek do podania"], "steps": ["Zmiksuj kvarg z jajkami na gładką masę.", "Dodaj proteinpulver, wanilię i słodzik — wymieszaj (nie miksuj długo, żeby masa nie była rzadka).", "Przełóż do papilotek/silikonowych foremek, wstaw na blachę.", "Piec 180°C ok. 25 min — aż wierzch się zrumieni, a środek zacznie się ścinać.", "Ostudź, podawaj z borówkami. Fajne też na zimno z lodówki!"], "tip": "Z kwargu o smaku wanilia możesz pominąć słodzik. Na 8 sztuk ~95 kcal i 11 g białka każda."}, {"title": "Kwarg pancakes proteinowe", "sub": "Puszyste placki — śniadanie z 20 g białka", "img": "img/r2.jpg", "time": "20 min", "macro": {"protein": 20, "kcal": 350}, "ingredients": ["200 g kvargu naturalnego", "2 jajka", "50 g płatków owsianych (drobnych)", "20 g proteinpulveru (wanilia)", "1 łyżeczka proszku do pieczenia", "Szczypta soli, słodzik", "Owoce i odrobina miodu do podania"], "steps": ["Zblenduj wszystko na jednolite ciasto (gęste jak śmietana).", "Odstaw 5 min, żeby płatki napęczniały.", "Smaż na suchej patelni/non-stick na małym ogniu ~2 min z każdej strony.", "Podawaj z jagodami/malinami i cienką nitką miodu."], "tip": "Ciasto będzie gęste — to dobrze, placki będą puszyste. Jeśli za gęste, dodaj łyżkę mleka."}, {"title": "Lody kwargowe (protein nice cream)", "sub": "Kremowe lody z zamrażarki — bez maszynki", "img": "img/r3.jpg", "time": "10 min + chłodzenie", "macro": {"protein": 22, "kcal": 240}, "ingredients": ["300 g mrożonych jagód/malini (rozmrożone 5 min)", "250 g kvargu naturalnego (zimnego)", "30 g waniliowego whey", "100 ml mleka (lub napoju)", "Opsjonalnie: słodzik, wanilia"], "steps": ["Blenduj wszystko na gładki krem — jagody muszą być lekko przymrożone, żeby masa była kremowa.", "Jedz od razu jako soft-serve albo zamroź 1–2 h na lody.", "Przed podaniem zostaw 10 min w temp. pokojowej."], "tip": "Wersja \"keto\": zamień jagody na 100 g malin i dodaj łyżkę masła orzechowego."}, {"title": "Kycklingkebab bowl", "sub": "Obiad po treningu — 45 g białka na miskę", "img": "img/r4.jpg", "time": "15 min", "macro": {"protein": 45, "kcal": 550}, "ingredients": ["200 g kycklingkebab (z Willys, ~18 g P/100 g)", "60 g ryżu (waga sucha) lub 250 g ugotowanego", "150 g kvargu naturalnego (sos: czosnek + koperek + sól + cytryna)", "Ogórek, pomidorki koktajlowe, czerwona cebula", "Oliwa, przyprawy (papryka wędzona, pieprz)"], "steps": ["Ugotuj ryż zgodnie z opisem na opakowaniu.", "Podgrzej kebab na patelni bez tłuszczu, aż złapie kolor.", "Wymieszaj kvarg z czosnkiem, koperkiem, solą i sokiem z cytryny.", "Złóż miskę: ryż → warzywa → kebab → sos. Posyp papryką wędzoną."], "tip": "Bez ryżu (na keto): podwój kebab i dodaj awokado — ~40 g P, ~25 g węglowodanów mniej."}, {"title": "Sałatka tuńczykowa high-protein", "sub": "Szybki lunch z puszki — 40 g białka", "img": "img/r5.jpg", "time": "10 min", "macro": {"protein": 40, "kcal": 380}, "ingredients": ["2 puszki tuńczyka w sosie własnym (odcedzone ~240 g)", "3 jajka na twardo", "Pół ogórka, 6 pomidorków, czerwona cebula", "2 łyżki kvargu/jogurtu naturalnego (zamiast majonezu)", "Musztarda, cytryna, koperek, sól, pieprz"], "steps": ["Jajka ugotuj na twardo (9 min), przepłucz zimną wodą, pokrój na ćwiartki.", "Tuńczyka odcedź, rozdrobnij widelcem, wymieszaj z kvargiem i musztardą.", "Dodaj warzywa, dopraw cytryną i koperkiem.", "Ułóż jajka na wierzchu. Podawaj z chrupkim pieczywem lub solo."], "tip": "Tuńczyk w sosie własnym = prawie czyste białko (25 g P/100 g) w pół ceny versji w oleju."}, {"title": "Mug cake proteinowy (2 min)", "sub": "Czekoladowy deser z mikrofalówki — 30 g białka", "img": "img/r6.jpg", "time": "5 min", "macro": {"protein": 30, "kcal": 290}, "ingredients": ["30 g czekoladowego proteinpulveru", "1 jajko", "15 g mąki migdałowej (lub 10 g kakao)", "50 ml mleka", "Szczypta proszku do pieczenia", "3–4 maliny do środka"], "steps": ["Wymieszaj wszystko w dużej kubku (żywnościowym) na gładkie ciasto.", "Wciśnij maliny do środka.", "Mikrofala 70–90 s (850 W) — zatrzymaj, gdy wierzch jeszcze lekko drży.", "Zjedz od razu, najlepiej z łyżką kvargu waniliowego na wierzchu 😉"], "tip": "Nie przesadź z mikrofalą — 10 s za dużo robi z tego oponkę. Drżący środek = idealny."}, {"title": "Czosnkowy dipp z kvargu", "sub": "Sos do wszystkiego: kebab, warzywa, chipsy proteinowe", "img": "img/r7.jpg", "time": "5 min", "macro": {"protein": 6, "kcal": 60}, "ingredients": ["250 g kvargu naturalnego", "1–2 ząbki czosnku (przez praskę)", "Koperek + szczypiorek", "Sól, pieprz, sok z cytryny", "Opcjonalnie: łyżka majonezu light dla kremowości"], "steps": ["Wymieszaj kvarg z czosnkiem i sokiem z cytryny.", "Dodaj posiekane zioła, dopraw solą i pieprzem.", "Schłodź 15 min — smaki się przegryzą.", "Podawaj do kycklingkebab, grilla, warzyw lub protein chipsów."], "tip": "Zamiast 250 kcal klasycznego sosu czosnkowego (majonez) ta wersja ma 60 kcal i 6 g białka na porcję."}, {"title": "Berry protein fluff", "sub": "Puszysty deser jak chmurka — 22 g białka", "img": "img/r8.jpg", "time": "10 min", "macro": {"protein": 22, "kcal": 220}, "ingredients": ["200 g kvargu naturalnego (zimnego)", "100 g mrożonych jagód (częściowo rozmrożonych)", "30 g waniliowego whey", "80–100 ml mleka", "Szczypta soli (pomaga ubić)"], "steps": ["Wrzuć wszystko do blendera lub wysokiego naczynia.", "Blenduj/miksuj 2–3 min — masa podwoi objętość i zrobi się puszysta.", "Przełóż do szklanek, udekoruj jagodami i miętą.", "Jedz łyżką jak mus — albo zamroź na semifreddo."], "tip": "Im zimniejsze składniki, tym lepiej się ubija. Serce deseru po treningu."}];
